import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract tenant context from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.user_id;
    req.role = payload.role;
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/reports/search', extractTenant, async (req, res) => {
  try {
    const { category, date_from, date_to, sort_by, order } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT r.id, r.title, r.category, r.created_at, r.author_id, r.summary 
                 FROM reports r WHERE r.tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND r.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (date_from) {
      query += ` AND r.created_at >= $${paramIdx}`;
      params.push(date_from);
      paramIdx++;
    }

    if (date_to) {
      query += ` AND r.created_at <= $${paramIdx}`;
      params.push(date_to);
      paramIdx++;
    }

    // Dynamic ORDER BY - vulnerable to SQL injection
    const allowedSorts = ['created_at', 'title', 'category'];
    const sortColumn = sort_by || 'created_at';
    const sortOrder = order && order.toUpperCase() === 'ASC' ? 'ASC' : 'DESC';

    // Developer thought allowedSorts check was applied but it's not enforced
    query += ` ORDER BY ${sortColumn} ${sortOrder}`;
    query += ` LIMIT 50`;

    const result = await pool.query(query, params);
    res.json({ reports: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/reports/export', extractTenant, async (req, res) => {
  const { report_ids, format } = req.body;
  if (!Array.isArray(report_ids) || report_ids.length === 0) {
    return res.status(400).json({ error: 'report_ids required' });
  }

  const placeholders = report_ids.map((_, i) => `$${i + 2}`).join(',');
  const query = `SELECT * FROM reports WHERE tenant_id = $1 AND id IN (${placeholders})`;
  const result = await pool.query(query, [req.tenantId, ...report_ids]);

  const exportId = crypto.randomUUID();
  res.json({ export_id: exportId, count: result.rows.length });
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000, () => {
  console.log(`Report service running on port ${process.env.PORT || 3000}`);
});
